-- Meal and exercise ideas generated by n8n each day. Separate from what you actually logged.
CREATE TABLE health_suggestions (
    id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    day        DATE NOT NULL DEFAULT current_date,
    kind       TEXT NOT NULL CHECK (kind IN ('meal', 'exercise')),
    slot       TEXT NOT NULL DEFAULT '' CHECK (slot IN ('', 'breakfast', 'lunch', 'dinner', 'snack')),
    text       TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (day, kind, slot)
);
